// Step 01: Pull & Normalize Weekly Spend, Conversions, and ROAS across Google Ads & Meta Ads
const rawInput = $input.first().json.body || $input.first().json || {};
const hasCustom = Boolean(rawInput.clientAccount);

const report = hasCustom ? rawInput : {
  clientAccount: 'Prime Retail Nigeria',
  accountOwnerEmail: 'account.lead@agency.com',
  reportingWeek: 'Nov 2 - Nov 8, 2026',
  googleAds: { spendUsd: 2450, conversions: 142, revenueUsd: 11270, roas: 4.6 },
  metaAds: { spendUsd: 1850, conversions: 98, revenueUsd: 6845, roas: 3.7 }
};

const totalSpend = report.googleAds.spendUsd + report.metaAds.spendUsd;
const totalConversions = report.googleAds.conversions + report.metaAds.conversions;
const totalRevenue = report.googleAds.revenueUsd + report.metaAds.revenueUsd;
const blendedRoas = Number((totalRevenue / totalSpend).toFixed(2));
const blendedCpa = Number((totalSpend / totalConversions).toFixed(2));

return [{
  json: {
    reportId: `ROAS-${Date.now()}`,
    clientAccount: report.clientAccount,
    accountOwnerEmail: report.accountOwnerEmail,
    reportingWeek: report.reportingWeek,
    googleAds: report.googleAds,
    metaAds: report.metaAds,
    blendedMetrics: {
      totalSpendUsd: totalSpend,
      totalConversions,
      totalRevenueUsd: totalRevenue,
      blendedRoas,
      blendedCpaUsd: blendedCpa
    },
    lookerStudioSheetStatus: 'SYNCED_TO_MASTER_SHEET'
  }
}];

