// Step 04: Deterministic Fallback & Dispatch to Gmail & Slack
const metrics = $('02. Google Ads & Meta Ads ROAS Aggregator -> Sheets & Looker Studio').first().json;
const aiRaw = $input.first().json;

let digest = {
  headline: `${metrics.clientAccount} Weekly ROAS Digest (${metrics.reportingWeek}): ${metrics.blendedMetrics.blendedRoas}x Blended ROAS`,
  executiveSummary: `Total Spend: $${metrics.blendedMetrics.totalSpendUsd} | Revenue: $${metrics.blendedMetrics.totalRevenueUsd} | Conversions: ${metrics.blendedMetrics.totalConversions} (CPA: $${metrics.blendedMetrics.blendedCpaUsd}). Google Ads led at ${metrics.googleAds.roas}x ROAS while Meta Ads delivered ${metrics.metaAds.roas}x ROAS.`,
  budgetRecommendation: 'Shift 15% of underperforming Meta ad-set spend into Google Performance Max top-converting SKU campaigns for next week.'
};

try {
  const text = aiRaw?.candidates?.[0]?.content?.parts?.[0]?.text;
  if (text) digest = JSON.parse(text);
} catch (e) {}

return [{
  json: {
    dispatchStatus: 'DIGEST_SENT_TO_GMAIL_AND_SLACK',
    clientAccount: metrics.clientAccount,
    recipient: metrics.accountOwnerEmail,
    lookerStudioSheetStatus: metrics.lookerStudioSheetStatus,
    blendedMetrics: metrics.blendedMetrics,
    executiveDigest: digest
  }
}];

const err = $input.first().json;
return [{
  json: {
    circuitBreakerStatus: 'ALERT_DISPATCHED',
    errorSummary: err?.execution?.error?.message || 'Unhandled ROAS digest workflow exception.'
  }
}];
